  world=Fixture(21);Clear(world);check(!world.CanStand(new WorldPoint(5,14),null,false),"Phase 29 the collapsed skybridge physically blocks ordinary walking before crossing");check(!Do(world,"roof29-repair"),"Phase 29 skybridge cannot be repaired without its actual construction stock");Take(world,21,4);Take(world,21,5);check(Do(world,"roof29-repair")&&world.HasDialogueFlag("flag.roof.21.repaired")&&world.CanStand(new WorldPoint(5,14),null,false)&&world.PartyLeader.Inventory.Count("item.roof.21.loot.5")==1,"Phase 29 bridge repair consumes one real scrap unit and persists a safe crossing");world.Save(path);check(World.Load(path).LowerMallProgress(221)!.Events.Contains("crossed"),"Phase 29 repaired crossing survives reload");
  world=Fixture(22);Clear(world);check(!Do(world,"roof29-repair"),"Phase 29 elevator repair refuses missing supplies and power");Take(world,22,0);Take(world,22,1);Add(world,world.Campaign!.Infrastructure!.GeneratorCost[0].ItemId);check(Do(world,"roof29-repair")&&world.PartyLeader.Inventory.Count("item.roof.22.loot.1")==0,"Phase 29 elevator repair consumes fuel and structural material");Do(world,"roof29-release");var broken=Take(world,22,5);check(broken.Broken&&broken.LoadedAmmunition?.Quantity==3&&Do(world,"roof29-pistol")&&!broken.Broken,"Phase 29 malfunctioning revolver must be repaired and retains its three rounds");
  world.StopAll();int slot=0;foreach(var p in world.Party)p.Pos=new Cell(34+slot%2,24+slot++/2);world.Reveal();string snapshot=JsonSerializer.Serialize(world);var preview=world.PreviewCampaignTravel("area.lower.east");check(preview.Allowed&&snapshot==JsonSerializer.Serialize(world),"Phase 29 real cargo lift preview is permitted and read-only after repairs");int clock=world.CampaignMinutes;check(world.TravelCampaignTo("area.lower.east")&&world.CampaignMinutes==clock+1,"Phase 29 repaired powered lift actually travels into the existing lower mall");world.Save(path);world=World.Load(path);world.CampaignMinutes=world.LowerMallProgress(222)!.RoofTimers["powerUntil"];world.ProcessSurvivalTime();check(!world.PreviewCampaignTravel("area.roof.22").Allowed,"Phase 29 cargo lift stops when its persisted local fuel expires");
