  world=Fixture(24);Clear(world);Take(world,24,4);check(Do(world,"roof29-flare")&&Do(world,"roof29-flare")&&Do(world,"roof29-flare")&&!Do(world,"roof29-flare"),"Phase 29 camp signal kit has exactly three saved uses");world.Save(path);check(World.Load(path).LowerMallProgress(224)!.RoofTimers["flares"]==0,"Phase 29 reload never refills spent signal flares");
  world=Fixture(25);Clear(world);int rounds=world.LowerMallProgress(225)!.RoofRolls["rounds"];check(rounds is >=2 and <=12&&world.Features.Single(f=>f.Id=="feature.roof.25.loot.4").Contents.Items.Single().Quantity==rounds,"Phase 29 pool lockbox holds a saved 2d6 of real independently valued rounds");world.Save(path);check(World.Load(path).LowerMallProgress(225)!.RoofRolls["rounds"]==rounds,"Phase 29 pool ammunition roll cannot change on reload");
