  // Rescue branches are selected naturally by the saved entry rolls, not synthesized by adding a recruit.
  World PoolBranch(uint seed)
  {
   var d=CampaignLoader.Clone(campaign);var start=d.Areas.Single(a=>a.Id=="area.roof.east");var origin=d.Areas.Single(a=>a.Id==d.StartAreaId);var crew=origin.Actors.Where(p=>!d.Actors.Single(a=>a.Id==p.ActorId).Enemy&&!d.Actors.Single(a=>a.Id==p.ActorId).Recruitable).ToArray();origin.Actors.RemoveAll(p=>crew.Contains(p));int i=0;foreach(var p in crew){p.Position=new(36+i++,11);start.Actors.Add(p);}d.StartAreaId=start.Id;var w=World.New(d);w.RandomState=seed;w.Reveal();if(!w.TravelCampaignTo("area.roof.25"))throw new Exception("Pool branch route failed");return w;
  }
